sys_script_vtable.script:
(function executeQuery(v_table, v_query) {


    var ipData = gs.getProperty('x_938076_now_utils.ipAddressData');
    var ipCount = ipData.split(",").length;
    var ipArr = [];

    for (var j = 0; j < ipCount; j++) {
        ipArr.push(ipData.split(",")[j]);
    }


    try {


        for (var i = 0; i < ipCount; i++) {

            var endPoint = gs.getProperty('x_938076_now_utils.geoAPIBaseUrl');
            var geoToken = gs.getProperty('x_938076_now_utils.geoAPITokenKey');
            var requestSent = endPoint + '/' + ipArr[i];


            var r = new sn_ws.RESTMessageV2('IPLookup', 'Get Geo Location Details');
            r.setStringParameterNoEscape('geoAPIToken', geoToken); //geoAPIToken
            r.setStringParameterNoEscape('base_url', endPoint); //base_url
            r.setStringParameterNoEscape('ipAddress', ipArr[i]); //inputIP from client call
            var requestBodyContent = r.getRequestBody();
            var response = r.execute();
            var responseBody = JSON.parse(response.getBody());
            var httpStatus = response.getStatusCode();
            var errorMessage = response.getErrorMessage();
            var errorCode = response.getErrorCode();

            var rowObj = {
                'sun_rise': responseBody.ip,
                'location': responseBody.continent_name,
                'moonset': responseBody.country_name_official,
                'moonrise': responseBody.state_prov,
                'sun_set': responseBody.zipcode
            };

            v_table.addRow(rowObj);

        }

    } catch (ex) {
        var message = ex.message;
        gs.info("Error " + message);
    }







})(v_table, v_query);
